 on a.sku_group = b.sku_group where DATE_TRUNC(\'month\', date) < DATE_TRUNC(\'month\', CURRENT_DATE) AND date BETWEEN DATEADD(month, -12, CURRENT_DATE) AND CURRENT_DATE AND size IS NOT NULL AND a.category IS NOT NULL and b.sku_group is not null ) select category, size_tag, case when size_tag = \'without_xs\' then 0 else ifnull(sum(case when size = \'XS\' then quant end)/sum(quant),0) end as xs_split, sum(case when size = \'S\' then quant end)/sum(quant) as s_split, sum(case when size = \'M\' then quant end)/sum(quant) as m_split, sum(case when size = \'L\' then quant end)/sum(quant) as l_split, sum(case when size = \'XL\' then quant end)/sum(quant) as xl_split, sum(case when size = \'XXL\' then quant end)/sum(quant) as xxl_split from size_wise_sales group by 1,2 ; create or replace table snitch_db.maplemonk.sku_group_xs_without_xs_eoq as with sku_size as ( select sku_group, case when SIZE = \'XS\' OR SIZE = \'28\' then \'XS\' WHEN SIZE = \'S\' OR SIZE = \'30\' THEN \'S\' WHEN SIZE = \'M\' OR SIZE = \'32\' THEN \'M\' WHEN SIZE = \'M\' OR SIZE = \'32\' THEN \'M\' WHEN SIZE = \'L\' OR SIZE = \'34\' THEN \'L\' WHEN SIZE = \'XL\' OR SIZE = \'36\' THEN \'XL\' when SIZE IN (\'XXL\', \'XXl\', \'2XL\', \'38\') THEN \'XXL\' WHEN SIZE = \'3XL\' OR SIZE = \'40\' THEN \'3XL\' WHEN SIZE = \'4XL\' OR SIZE = \'42\' then \'4XL\' WHEN SIZE = \'5XL\' OR SIZE = \'44\' then \'5XL\' WHEN SIZE = \'6XL\' OR SIZE = \'46\' THEN \'6XL\' WHEN SIZE = \'7XL\' OR SIZE = \'48\' THEN \'7XL\' WHEN SIZE = \'8XL\' OR SIZE = \'48\' THEN \'8XL\' end as size, from snitch_db.maplemonk.cut_size_analysis ), sku_sizes_aggregated as ( select sku_group, listagg(size, \', \') within group (order by size) as sizes_available from ( select distinct sku_group, size from sku_size where size is not null ) group by sku_group ) select sku_group, case when sizes_available like \'%XS%\' then \'with_xs\' else \'without_xs\' end as size_tag from sku_sizes_aggregated ;",
